def skill():
    t = 8*sqrt(2) / (2*sqrt(2))
    return simplify(t * 2)

def _sol():
    u, t = symbols('u t', positive=True)
    ds = [v for v in solve((u**3 - u)**2 - u**2, u) if v > 1]
    u0 = ds[0]
    A = (t, u0); B = (3*t, u0**3); C = (3*t, 0)
    area = Abs((B[0]-A[0])*(C[1]-A[1]) - (C[0]-A[0])*(B[1]-A[1])) / 2
    ts = solve(Eq(area, 8*sqrt(2)), t)
    return [simplify(tt * u0**2) for tt in ts]

def standard():
    return _sol()[0]

def unique():
    return sorted(set(_sol()))
